import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { ApiError } from './http';

export type TranscriptLine = {
    id: string;
    text: string;
    final: boolean;
    detectedLanguage: string | null;
    updatedAt: string;
};

export type StoredTranscript = {
    sessionId: string;
    createdAt: string;
    language: string;
    lines: TranscriptLine[];
};

export type TranscriptStore = {
    read(sessionId: string): Promise<StoredTranscript | null>;
    save(session: StoredTranscript): Promise<void>;
};

const SESSION_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function assertSessionId(sessionId: string) {
    if (!SESSION_ID.test(sessionId))
        throw new ApiError(400, 'Use a session id.');
    return sessionId;
}

export function upsertLine(existing: StoredTranscript | null, sessionId: string, language: string, line: TranscriptLine): StoredTranscript {
    const current = existing ?? { sessionId, createdAt: line.updatedAt, language, lines: [] };
    const index = current.lines.findIndex(item => item.id === line.id);
    if (index === -1) {
        if (current.lines.length >= 200)
            throw new ApiError(413, 'This session has too many lines.');
        return { ...current, lines: [...current.lines, line] };
    }
    if (current.lines[index].final)
        throw new ApiError(409, 'That line is already saved.');
    const lines = current.lines.slice();
    lines[index] = line;
    return { ...current, lines };
}

export function createFileTranscriptStore(directory = path.join(process.cwd(), '.data', 'transcripts')): TranscriptStore {
    const fileFor = (sessionId: string) => path.join(directory, `${assertSessionId(sessionId)}.json`);
    return {
        async read(sessionId) {
            try {
                return JSON.parse(await readFile(fileFor(sessionId), 'utf8')) as StoredTranscript;
            }
            catch (error) {
                if ((error as NodeJS.ErrnoException).code === 'ENOENT')
                    return null;
                throw new ApiError(500, 'The saved transcript could not be read.');
            }
        },
        async save(session) {
            await mkdir(directory, { recursive: true });
            const file = fileFor(session.sessionId);
            const temporary = `${file}.${process.pid}.tmp`;
            await writeFile(temporary, JSON.stringify(session), 'utf8');
            await writeFile(file, JSON.stringify(session), 'utf8');
            const { rm } = await import('node:fs/promises');
            await rm(temporary, { force: true }).catch(() => undefined);
        }
    };
}

let activeStore: TranscriptStore = createFileTranscriptStore();

export function transcriptStore() {
    return activeStore;
}

export function setTranscriptStore(store: TranscriptStore) {
    activeStore = store;
}

import { z } from 'zod';
import { ApiError, requireKey } from './http';

export const WISPR_SOCKET_URL = 'wss://platform-api.wisprflow.ai/api/v1/dash/client_ws';
const TOKEN_URL = 'https://platform-api.wisprflow.ai/api/v1/dash/generate_access_token';

const tokenSchema = z.object({
    access_token: z.string().trim().min(1).max(4096),
    expires_in: z.number().int().positive().max(86400)
}).strict();

/** Wispr documents two-letter ISO 639-1 codes. Swiss German is not one of them; `de` is the code that covers German speech. */
export function wisprLanguage() {
    const value = process.env.WISPR_LANGUAGE || 'de';
    if (!/^[a-z]{2}$/.test(value))
        throw new ApiError(500, 'WISPR_LANGUAGE must be a two-letter language code.');
    return value;
}

export function requireLocalDemo(request: Request) {
    const url = new URL(request.url);
    const authority = request.headers.get('host') ?? url.host;
    if (!['http:', 'https:'].includes(url.protocol) ||
        !/^(localhost|127\.0\.0\.1|\[::1\])(:\d{1,5})?$/i.test(authority)) {
        throw new ApiError(403, 'Live transcription is available locally. A public deployment needs authentication.');
    }
}

export async function issueWisprToken(sessionId: string, signal?: AbortSignal) {
    const key = requireKey('WISPR_API_KEY');
    const language = wisprLanguage();
    const controller = new AbortController();
    const abort = () => controller.abort();
    signal?.addEventListener('abort', abort, { once: true });
    const timer = setTimeout(abort, 10000);
    try {
        const response = await fetch(TOKEN_URL, {
            method: 'POST',
            headers: { authorization: `Bearer ${key}`, 'content-type': 'application/json' },
            body: JSON.stringify({ client_id: sessionId, duration_secs: 3600 }),
            signal: controller.signal
        });
        if (!response.ok)
            throw new ApiError(502, 'Wispr could not start a transcription session. Please try again.');
        const parsed = tokenSchema.safeParse(await response.json());
        if (!parsed.success || parsed.data.access_token === key)
            throw new ApiError(502, 'Wispr could not start a transcription session. Please try again.');
        return {
            accessToken: parsed.data.access_token,
            expiresIn: parsed.data.expires_in,
            socketUrl: WISPR_SOCKET_URL,
            language: [language],
            context: {
                app: { name: 'AnyResets', type: 'other' as const },
                dictionary_context: ['Grüezi', 'Merci vilmal', 'gäl', 'luege']
            }
        };
    }
    catch (error) {
        if (error instanceof ApiError)
            throw error;
        throw new ApiError(502, 'Wispr could not start a transcription session. Please try again.');
    }
    finally {
        clearTimeout(timer);
        signal?.removeEventListener('abort', abort);
    }
}

import { z } from 'zod';
import { handle, json, readJson } from '@/lib/server/http';
import { assertSessionId } from '@/lib/server/transcript-store';
import { issueWisprToken, requireLocalDemo } from '@/lib/server/wispr';

export const runtime = 'nodejs';

const bodySchema = z.object({ sessionId: z.string() }).strict();

export async function POST(request: Request) {
    return handle(request, async () => {
        requireLocalDemo(request);
        const { sessionId } = await readJson(request, bodySchema);
        assertSessionId(sessionId);
        return json(await issueWisprToken(sessionId, request.signal));
    });
}

import { z } from 'zod';
import { ApiError, handle, json, readJson } from '@/lib/server/http';
import { assertSessionId, transcriptStore, upsertLine, type TranscriptLine } from '@/lib/server/transcript-store';
import { wisprLanguage } from '@/lib/server/wispr';

export const runtime = 'nodejs';

const lineSchema = z.object({
    sessionId: z.string(),
    lineId: z.string().trim().min(1).max(64),
    text: z.string().trim().min(1).max(8000),
    final: z.boolean(),
    detectedLanguage: z.string().trim().min(2).max(16).nullable().optional()
}).strict();

export async function GET(request: Request) {
    return handle(request, async () => {
        const sessionId = assertSessionId(new URL(request.url).searchParams.get('sessionId') ?? '');
        const saved = await transcriptStore().read(sessionId);
        if (!saved)
            throw new ApiError(404, 'No transcript is saved for that session.');
        return json(saved);
    });
}

export async function POST(request: Request) {
    return handle(request, async () => {
        const input = await readJson(request, lineSchema);
        const sessionId = assertSessionId(input.sessionId);
        const store = transcriptStore();
        const line: TranscriptLine = {
            id: input.lineId,
            text: input.text,
            final: input.final,
            detectedLanguage: input.detectedLanguage ?? null,
            updatedAt: new Date().toISOString()
        };
        const saved = upsertLine(await store.read(sessionId), sessionId, wisprLanguage(), line);
        await store.save(saved);
        return json(saved);
    });
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { POST as issueToken } from '@/app/api/wispr/token/route';
import { GET, POST as saveLine } from '@/app/api/transcripts/route';
import { resetRateLimit } from './http';
import { setTranscriptStore, upsertLine, type StoredTranscript, type TranscriptStore } from './transcript-store';

const fetchMock = vi.fn<typeof fetch>();
const sessionId = '11111111-1111-4111-8111-111111111111';
const request = (url: string, init: RequestInit = {}, host = '127.0.0.1:3000') =>
    new Request(url, { ...init, headers: { host, origin: `http://${host}`, 'content-type': 'application/json', ...init.headers } });

function memoryStore() {
    const sessions = new Map<string, StoredTranscript>();
    const store: TranscriptStore = {
        async read(id) { return sessions.get(id) ?? null; },
        async save(session) { sessions.set(session.sessionId, session); }
    };
    return { store, sessions };
}

describe('Wispr token', () => {
    beforeEach(() => {
        resetRateLimit();
        vi.stubEnv('WISPR_API_KEY', 'fl-server-secret');
        vi.stubEnv('WISPR_LANGUAGE', 'de');
        vi.stubGlobal('fetch', fetchMock);
        fetchMock.mockReset();
    });
    afterEach(() => { vi.unstubAllEnvs(); vi.unstubAllGlobals(); });

    it('mints a client token and does not return the org key', async () => {
        fetchMock.mockResolvedValue(Response.json({ access_token: 'client-jwt', expires_in: 3600 }));
        const response = await issueToken(request('http://127.0.0.1:3000/api/wispr/token', {
            method: 'POST', body: JSON.stringify({ sessionId })
        }));
        expect(response.status).toBe(200);
        const body = await response.json();
        expect(body.accessToken).toBe('client-jwt');
        expect(body.language).toEqual(['de']);
        expect(body.socketUrl).toBe('wss://platform-api.wisprflow.ai/api/v1/dash/client_ws');
        expect(JSON.stringify(body)).not.toContain('fl-server-secret');
        expect(fetchMock).toHaveBeenCalledWith('https://platform-api.wisprflow.ai/api/v1/dash/generate_access_token', expect.objectContaining({
            method: 'POST',
            headers: { authorization: 'Bearer fl-server-secret', 'content-type': 'application/json' }
        }));
    });

    it('refuses a missing key and a public host', async () => {
        vi.stubEnv('WISPR_API_KEY', '');
        expect((await issueToken(request('http://127.0.0.1:3000/api/wispr/token', { method: 'POST', body: JSON.stringify({ sessionId }) }))).status).toBe(503);
        vi.stubEnv('WISPR_API_KEY', 'fl-server-secret');
        expect((await issueToken(request('http://127.0.0.1:3000/api/wispr/token', { method: 'POST', body: JSON.stringify({ sessionId }) }, 'example.com'))).status).toBe(403);
        expect(fetchMock).not.toHaveBeenCalled();
    });
});

describe('saved transcripts', () => {
    const memory = memoryStore();
    beforeEach(() => {
        resetRateLimit();
        memory.sessions.clear();
        setTranscriptStore(memory.store);
        vi.stubEnv('WISPR_LANGUAGE', 'de');
    });
    afterEach(() => vi.unstubAllEnvs());

    it('stores a streaming line and then locks the final text', async () => {
        const first = await saveLine(request('http://127.0.0.1:3000/api/transcripts', {
            method: 'POST', body: JSON.stringify({ sessionId, lineId: 'line-1', text: 'Grüezi', final: false, detectedLanguage: 'de' })
        }));
        expect(first.status).toBe(200);
        const updated = await saveLine(request('http://127.0.0.1:3000/api/transcripts', {
            method: 'POST', body: JSON.stringify({ sessionId, lineId: 'line-1', text: 'Grüezi, wie gaht s?', final: true, detectedLanguage: 'de' })
        }));
        expect((await updated.json()).lines[0].text).toBe('Grüezi, wie gaht s?');
        const locked = await saveLine(request('http://127.0.0.1:3000/api/transcripts', {
            method: 'POST', body: JSON.stringify({ sessionId, lineId: 'line-1', text: 'changed', final: true })
        }));
        expect(locked.status).toBe(409);
        const saved = await GET(request(`http://127.0.0.1:3000/api/transcripts?sessionId=${sessionId}`));
        expect((await saved.json()).lines).toHaveLength(1);
    });

    it('numbers nothing into a missing session', async () => {
        expect((await GET(request(`http://127.0.0.1:3000/api/transcripts?sessionId=${sessionId}`))).status).toBe(404);
    });

    it('keeps an unfinished line replaceable', () => {
        const once = upsertLine(null, sessionId, 'de', { id: 'a', text: 'one', final: false, detectedLanguage: null, updatedAt: '2026-10-10T10:00:00.000Z' });
        const twice = upsertLine(once, sessionId, 'de', { id: 'a', text: 'one two', final: false, detectedLanguage: 'de', updatedAt: '2026-10-10T10:00:01.000Z' });
        expect(twice.lines).toHaveLength(1);
        expect(twice.lines[0].text).toBe('one two');
    });
});

